import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, smoothstep, uv, color } from 'three/tsl';
import { gsap } from 'gsap';
import { OrbitControls } from '@/primitives';
import { /* placeholder for primitives import */ } from '@/primitives';

/**
 * @typedef {Object} NodeConfig
 * @property {string} imageUrl
 * @property {Object} visualSpec
 * @property {Array} textContent
 * @property {Array<{name:string,params:Object,trigger:string}>} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {any} textureLoader
 * @property {any} emit
 * @property {Object} primitives
 * @property {any} fontAtlas
 */

/**
 * Create the pedestal material study node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CylinderGeometry, TorusKnotGeometry, DirectionalLight, AmbientLight, Vector3 } =
    ctx.THREE;

  const root = new Group();

  // ---------- Backdrop Gradient ----------
  const backdropGeo = new PlaneGeometry(7, 6);
  const uvY = uv().y;

  const gradColor0 = color('#0b0b10');
  const gradColor1 = color('#101017');
  const gradColor2 = color('#16161d');

  const t0 = smoothstep(float(0.0), float(0.7), uvY);
  const t1 = smoothstep(float(0.7), float(1.0), uvY);
  const mixed01 = mix(gradColor0, gradColor1, t0);
  const gradientNode = mix(mixed01, gradColor2, t1);

  const backdropMat = new MeshBasicNodeMaterial({ color: gradientNode });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -3);
  root.add(backdrop);

  // ---------- Pedestal ----------
  const pedestalGeo = new CylinderGeometry(1.1, 1.1, 0.5, 64, 1);
  const pedestalMat = new MeshStandardNodeMaterial({
    color: '#14141a',
    roughness: 0.7,
    metalness: 0.35,
  });
  const pedestal = new Mesh(pedestalGeo, pedestalMat);
  pedestal.position.set(0, -0.25, 0);
  root.add(pedestal);

  // ---------- Contact Shadow ----------
  const shadowGeo = new PlaneGeometry(3, 3);
  const uvDist = uv().length();
  const shadowAlpha = smoothstep(float(1.5), float(1.5 - 0.4), uvDist);
  const shadowMat = new MeshBasicNodeMaterial({ color: '#000000', opacity: shadowAlpha, transparent: true });
  const shadowPlane = new Mesh(shadowGeo, shadowMat);
  shadowPlane.rotation.x = -Math.PI / 2;
  shadowPlane.position.set(0, -0.36, 0);
  root.add(shadowPlane);

  // ---------- Torus Knot ----------
  const knotGeo = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMat = new MeshStandardNodeMaterial({
    color: '#e8ecf2',
    metalness: 0.55,
    roughness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
    anisotropy: 0.9,
  });
  const knot = new Mesh(knotGeo, knotMat);
  knot.position.set(0, 0.4, 0);
  root.add(knot);

  // Load brushed-metal roughness map and assign when ready
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texturePromise.then((tex) => {
    knotMat.roughnessMap = tex;
    knotMat.normalMap = tex; // using same map for demonstration
    knotMat.needsUpdate = true;
  });

  // ---------- Text ----------
  const texts = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of texts) {
    const opts = {
      fontSize: item.typography?.fontSize ?? (item.role === 'headline' ? 68 : 18),
      color: '#e8ecf2',
      align: 'center',
    };
    const textObj = ctx.fontAtlas.createText(item.text, opts);
    const yOffset = item.role === 'headline' ? -1.2 : -1.6;
    textObj.position.set(0, yOffset, 0);
    root.add(textObj);
  }

  // ---------- Lights ----------
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 2, 3);
  root.add(keyLight);

  const rimLight = new DirectionalLight('#ff2a38', 0.6);
  rimLight.position.set(-2, -2, -3);
  root.add(rimLight);

  const ambient = new AmbientLight(0xffffff, 0.6);
  root.add(ambient);

  // ---------- Cinematic Primitives ----------
  const primitiveHandles = [];
  for (const prim of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives[prim.name];
    if (fn) {
      const handle = fn(root, prim.params);
      primitiveHandles.push(handle);
    }
  }

  // ---------- Cleanup ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    // dispose texture
    texturePromise.then((tex) => {
      tex.dispose();
    });
    // dispose materials
    knotMat.dispose();
    pedestalMat.dispose();
    backdropMat.dispose();
    shadowMat.dispose();
    // dispose geometries
    knotGeo.dispose();
    pedestalGeo.dispose();
    backdropGeo.dispose();
    shadowGeo.dispose();
    // cleanup primitives
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }
    // kill any GSAP timelines (none used directly here)
    gsap.globalTimeline.clear();
  };

  return root;
}
